proc ::_LAN15::InitializeTargetLanSettings { } {
	variable LanCfg

	foreach ChanName [GetLanChannels] {
		set LanCfg($ChanName,Initialized)	0
		set LanCfg($ChanName,ChannelNumber)	[ResolveLanChannelNumber $ChanName]		
		set LanCfg($ChanName,IPaddress)	[ftf_getconfig Target_IPAddr($ChanName)]
		set LanCfg($ChanName,MACaddress) [GetGlobalMacAddress Target_MACAddr($ChanName)]
		if {$LanCfg($ChanName,IPaddress) != "" && $LanCfg($ChanName,MACaddress) != ""} {
			set LanCfg($ChanName,Initialized) 1
		}
	}

	foreach element [lsort -dictionary [array names LanCfg]] {
		set ChanName [lindex [split $element ,] 0]
		set index [lindex [split $element ,] 1]
		imsg 2 "$ChanName $index: $LanCfg($element)" v1 tag=darkblue
	}
}


