		# end
		if {$cerr} {
			lappend result [list $description $_FTF_Error(INIT_FAILED)]
			continue
		}

		# Run child
		set cresult [ftf_runtest $child]
		set ferr [lindex $cresult 0]

		# Cleanup after child
		set cresult [ftf_cleanuptest $child]
		set terr [lindex $cresult 0]

		if {$ferr} {
			lappend result [list $description $ferr]
		} elseif {$terr} {
			lappend result [list $description $_FTF_Error(CLEANUP_FAILED)]
		} elseif {[get_test_fail_count $child]} {
			lappend result [list $description $_FTF_Error(TEST_FAILED)]
		} elseif {[get_test_pass_count $child]} {
			lappend result [list $description 0]
		} elseif {[get_test_na_count $child]} {
			lappend result [list $description $_FTF_Error(TEST_NOT_APPLICABLE)]
		} elseif {[get_test_ni_count $child]} {
			lappend result [list $description $_FTF_Error(TEST_NOT_IMPLEMENTED)]
		} elseif {[get_test_warn_count $child]} {
			lappend result [list $description $_FTF_Error(TEST_WARNING)]
		} else {
			lappend result [list $description $_FTF_Error(TEST_NO_RESULT)]
		}

		# User abort?
		if {[ftf_stopcheck]} {


			set Abort_VDT(Abort_prompt) [list y "Abort? y to abort, n to continue with next test." y]

			#ask the user to n "skip test?" or  y "really quit?"


			#namespace is weird, use "Private" _ftf_getvar from ftf_vdt.tcl
			set ns [namespace current]
			_ftf_getvar $ns Abort_prompt 1 Abort_VDT			

			switch -- $Abort_prompt {
				y	{ imsg 5 "Aborting at user request..." v0 tag=red; break}
				n	{ imsg 5 "Continuted to next test" v0 tag=blue; set _FTF_UI_Event(STOPREQ) 0}
				default	{ imsg 5 "The user choose to abort(by canceling the dialog box)." v0 tag=red; break}
			}

}

		ftf_pause 3 "Pausing..."
	}

	return $result
}


