proc _ftf_ui_event { uievent {arg1 ""} {arg2 ""} } {
	global _FTF_Running
	global _FTF_UI_Event
	global _FTF_TestRunning

	set testRunning $_FTF_Running

	switch -- $uievent {
		STOPREQ {
			if { $_FTF_Running } {
				set _FTF_UI_Event(STOPREQ) 1
				ftf_msg "Stop requested" "" "tag=red"
			}
		}
		PAUSEREQ {
			if { $_FTF_Running } {
				set _FTF_UI_Event(PAUSEREQ) 1
				ftf_msg "View requested" "" "tag=pink"
			}
		}		
		CADCLOSEREQ {
			set wid $arg1
			set ns $arg2
			if { $_FTF_Running } {
				set testRunning [_ftf_isrunning $ns]
				if { $testRunning \
					&& ![info exists _FTF_UI_Event(CADCLOSEREQ,$wid)] } {
					set _FTF_UI_Event(CADCLOSEREQ,$wid) $ns
					ftf_msg "Window close requested" "" "tag=red"
				}
			}
		}
		CADCLOSED {
			set wid $arg1
			if { [info exists _FTF_UI_Event(CADCLOSEREQ,$wid)] } {
				unset _FTF_UI_Event(CADCLOSEREQ,$wid)
			}
		}
	}
	return $testRunning
}

